'use strict';
// Reads an approved (or draft) spec and produces a Playwright regression spec: one test per
// acceptance scenario, tagged with its REQ id so `sdd verify` counts it as that requirement's test,
// plus one skeleton per requirement that has no scenario yet. Generated files are meant to be
// filled in with real selectors/assertions for the project's UI, not run as-is.
const fs = require('fs');
const path = require('path');
const { readText, mkdirp, exists } = require('./util');
const { specsDir, parseSpec, parseScenarios } = require('./spec');

const BEGIN = '// SPECPILOT:GENERATED-BEGIN (regenerated by `sdd gen-tests`; edit below this line, not above it)';
const END = '// SPECPILOT:GENERATED-END';

function jsString(s) { return JSON.stringify(String(s).trim()); }

function testBody(reqId, scenario) {
  if (scenario && scenario.given) {
    return `  // Given ${scenario.given}
  // When ${scenario.when}
  // Then ${scenario.then}
  await use.ui(page, ${jsString(scenario.given)});
  await use.act(page, ${jsString(scenario.when)});
  await use.expect(page, ${jsString(scenario.then)});`;
  }
  return `  // TODO: no acceptance scenario is written for ${reqId} yet. Add one to spec.md section 6,
  // then re-run \`sdd gen-tests\`, or replace this with a manual Playwright assertion.
  test.fixme(true, ${jsString(`${reqId}: acceptance scenario not yet specified`)});`;
}

function render(feature, spec, scenarios) {
  const byReq = new Map();
  for (const s of scenarios) (byReq.get(s.req) || byReq.set(s.req, []).get(s.req)).push(s);
  const cases = spec.reqs.map((req) => {
    const list = byReq.get(req) || [null];
    return list.map((s, i) => {
      const title = s && s.raw ? `${req}: ${s.raw}` : `${req}`;
      return `  test(${jsString(title)}, async ({ page }) => {\n${testBody(req, s)}\n  });`;
    }).join('\n\n');
  }).join('\n\n');

  return `// Generated by \`sdd gen-tests ${feature}\` from .sdd/specs/${feature}/spec.md — do not hand-edit above the marker.
// Each test's title carries the requirement id it proves, so \`sdd verify\` counts it automatically.
'use strict';
const { test } = require('@playwright/test');
const use = require('../support/ui-connector');

test.describe(${jsString(feature)}, () => {
${BEGIN}
${cases || '  // No requirements found in spec.md yet.'}
${END}

  // Add scenarios spec.md does not cover yet (regressions, edge cases) below. They survive regeneration.
});
`;
}

/** Generate or regenerate the Playwright file for a feature. Preserves hand-written lines after END. */
function genTests(root, feature, { outDir = 'tests/e2e' } = {}) {
  const specPath = path.join(specsDir(root), feature, 'spec.md');
  const text = readText(specPath);
  if (text == null) throw new Error(`No spec.md for feature "${feature}" (run: sdd new ${feature})`);
  const spec = parseSpec(text);
  if (!spec.reqs.length) throw new Error(`spec.md for "${feature}" defines no REQ- requirements yet`);
  const scenarios = parseScenarios(text);
  const file = path.join(root, outDir, `${feature}.spec.js`);
  const fresh = render(feature, spec, scenarios);
  const prev = readText(file);
  mkdirp(path.dirname(file));
  if (prev == null || !prev.includes(END)) { fs.writeFileSync(file, fresh); return { file, created: prev == null }; }
  const tail = prev.slice(prev.indexOf(END) + END.length);
  fs.writeFileSync(file, fresh.slice(0, fresh.indexOf(END) + END.length) + tail);
  return { file, created: false };
}

module.exports = { genTests, render };
